// Interpreta caracteres de formulários codificados em URL.
static void decodificar_parametro(char *dst,size_t n,const char *src,size_t len){size_t j=0;for(size_t i=0;i<len&&j+1<n;i++){if(src[i]=='+' )dst[j++]=' ';else if(src[i]=='%'&&i+2<len&&isxdigit((unsigned char)src[i+1])&&isxdigit((unsigned char)src[i+2])){char h[3]={src[i+1],src[i+2],0};dst[j++]=(char)strtol(h,NULL,16);i+=2;}else if(src[i]!='\r'&&src[i]!='\n'&&src[i]!='\t'&&src[i]!='|')dst[j++]=src[i];}dst[j]=0;}
// Procura uma chave no formulário e extrai seu valor.
static void obter_parametro(const char *q,const char *key,char *dst,size_t n){dst[0]=0;if(!q)return;size_t k=strlen(key);while(*q){const char *end=strchr(q,'&');if(!end)end=q+strlen(q);if((size_t)(end-q)>k&&strncmp(q,key,k)==0&&q[k]=='='){decodificar_parametro(dst,n,q+k+1,(size_t)(end-q-k-1));return;}q=*end?end+1:end;}}
// Lê um parâmetro e converte para inteiro.
static int obter_numero_parametro(const char *q,const char *key){char b[32];obter_parametro(q,key,b,sizeof b);return atoi(b);}
