// Compara termos ignorando diferenças de maiúsculas/minúsculas ASCII.
static int contem_texto(const char *s,const char *q){if(!q||!*q)return 1;size_t n=strlen(q);for(;*s;s++){size_t j=0;while(j<n&&s[j]&&tolower((unsigned char)s[j])==tolower((unsigned char)q[j]))j++;if(j==n)return 1;}return 0;}
