// Calcula indicadores e exibe a página inicial e livros em destaque.
static void painel_inicial(void){cabecalho_pagina("Empréstimo de Livros",NULL);int disp=0,ativos=0;for(int i=0;i<quantidade_livros;i++)disp+=livros[i].disponivel;for(int i=0;i<quantidade_emprestimos;i++)ativos+=emprestimos[i].ativo;escrever_html("<section class='hero'><h2>Sua próxima leitura começa aqui</h2><p>Explore o acervo, descubra títulos e acompanhe seus empréstimos.</p><a class='btn' href='/livros'>Explorar catálogo →</a></section><div class='cards'>");const char *names[]={"Títulos cadastrados","Exemplares disponíveis","Leitores","Empréstimos ativos"};int vals[]={quantidade_livros,disp,quantidade_usuarios,ativos};for(int i=0;i<4;i++){escrever_html("<div class='stat'><small>");escrever_html(names[i]);escrever_html("</small><strong>");escrever_numero(vals[i]);escrever_html("</strong></div>");}escrever_html("</div><div class='toolbar'><a class='btn' href='/livro'>+ Cadastrar livro</a><a class='btn secondary' href='/novoemprestimo'>+ Novo empréstimo</a></div><h2>Acervo em destaque</h2><div class='grid'>");for(int i=0;i<quantidade_livros&&i<8;i++)cartao_livro(&livros[i]);escrever_html("</div>");rodape_pagina();}
