// Recebe dados dos formulários e chama as regras de biblioteca.c.
static void processar_acao(const char *q){char op[40];obter_parametro(q,"op",op,sizeof op);int ok=0,id=obter_numero_parametro(q,"id");if(!strcmp(op,"livro")){Livro l={0};l.id=id;obter_parametro(q,"titulo",l.titulo,sizeof l.titulo);obter_parametro(q,"autor",l.autor,sizeof l.autor);obter_parametro(q,"editora",l.editora,sizeof l.editora);if(id){Livro *old=buscar_livro(id);if(old)snprintf(l.capa,sizeof l.capa,"%s",old->capa);}l.ano=obter_numero_parametro(q,"ano");l.total=obter_numero_parametro(q,"total");if(strstr(l.capa,"..")||strchr(l.capa,'/')||strchr(l.capa,'\\'))l.capa[0]=0;ok=id?editar_livro(l):cadastrar_livro(l);if(ok&&dados_imagem_enviada&&tamanho_imagem_enviada){Livro *saved=id?buscar_livro(id):&livros[quantidade_livros-1];if(saved){char fn[160],tmp[200];snprintf(fn,sizeof fn,"livro_%d.%s",saved->id,extensao_imagem_enviada);snprintf(tmp,sizeof tmp,"capas/%s",fn);FILE *fp=fopen(tmp,"wb");if(fp){size_t written=fwrite(dados_imagem_enviada,1,tamanho_imagem_enviada,fp);int closed=fclose(fp);if(written==tamanho_imagem_enviada&&closed==0){snprintf(saved->capa,sizeof saved->capa,"%s",fn);ok=salvar();}else ok=0;}else ok=0;}}}else if(!strcmp(op,"usuario")){Usuario u={0};u.id=id;obter_parametro(q,"nome",u.nome,sizeof u.nome);obter_parametro(q,"cpf",u.cpf,sizeof u.cpf);obter_parametro(q,"telefone",u.telefone,sizeof u.telefone);obter_parametro(q,"email",u.email,sizeof u.email);ok=id?editar_usuario(u):cadastrar_usuario(u);}else if(!strcmp(op,"del_livro"))ok=excluir_livro(id);else if(!strcmp(op,"del_usuario"))ok=excluir_usuario(id);else if(!strcmp(op,"emprestar")){char a[16],b[16];obter_parametro(q,"retirada",a,sizeof a);obter_parametro(q,"prevista",b,sizeof b);ok=emprestar(obter_numero_parametro(q,"livro"),obter_numero_parametro(q,"usuario"),a,b);}else if(!strcmp(op,"devolver")){char a[16];obter_parametro(q,"data",a,sizeof a);ok=devolver(id,a);}cabecalho_pagina(ok?"Operação concluída":"Operação não realizada",ok?"Os dados foram atualizados e salvos.":"Confira os campos, IDs, CPF repetido, datas, disponibilidade ou vínculos ativos.");escrever_html("<div class='toolbar'><a class='btn' href='/'>Painel</a><a class='btn secondary' href='/livros'>Livros</a><a class='btn secondary' href='/usuarios'>Leitores</a><a class='btn secondary' href='/emprestimos'>Empréstimos</a></div>");rodape_pagina();}
// Lê imagem da pasta capas e a transmite ao navegador.
static void enviar_capa(const char *path){const char *name=path+7;if(!*name||strstr(name,"..")||strchr(name,'/')||strchr(name,'\\'))return;char file[256];snprintf(file,sizeof file,"capas/%s",name);FILE *f=fopen(file,"rb");if(!f)return;const char *ext=strrchr(name,'.');const char *mime=ext&&!strcmp(ext,".png")?"image/png":ext&&(!strcmp(ext,".jpg")||!strcmp(ext,".jpeg"))?"image/jpeg":ext&&!strcmp(ext,".bmp")?"image/bmp":NULL;if(!mime){fclose(f);return;}char h[128];snprintf(h,sizeof h,"HTTP/1.1 200 OK\r\nContent-Type: %s\r\nConnection: close\r\n\r\n",mime);enviar_texto(h);char b[8192];size_t n;while((n=fread(b,1,sizeof b,f))>0)send(cliente,b,(int)n,0);fclose(f);}
static const unsigned char *localizar_bytes(const unsigned char *p,size_t n,const char *needle,size_t m){if(m>n)return NULL;for(size_t i=0;i<=n-m;i++)if(!memcmp(p+i,needle,m))return p+i;return NULL;}
// Codifica caracteres para preservar valores dos campos.
static void anexar_codificado(char *outbuf,size_t cap,size_t *used,const char *key,const unsigned char *val,size_t n){
  if(*used+strlen(key)+2>=cap)return;
  *used+=(size_t)snprintf(outbuf+*used,cap-*used,"%s%s=",*used?"&":"",key);
  for(size_t i=0;i<n&&*used+4<cap;i++){unsigned char c=val[i];if(isalnum(c)||c=='-'||c=='_'||c=='.'){outbuf[(*used)++]=c;}else{sprintf(outbuf+*used,"%%%02X",c);*used+=3;}}
  outbuf[*used]=0;
}
// Interpreta multipart/form-data, valida assinatura da imagem e salva o cadastro.
static void processar_formulario_com_imagem(const char *content_type,const unsigned char *body,size_t n){
  const char *b=strstr(content_type,"boundary=");if(!b){cabecalho_pagina("Envio inválido","Limite do formulário não encontrado.");rodape_pagina();return;}
  b+=9;char boundary[110];size_t bl=0;while(b[bl]&&b[bl]!=';'&&b[bl]!='\r'&&bl<95)bl++;if(bl<3){cabecalho_pagina("Envio inválido",NULL);rodape_pagina();return;}
  snprintf(boundary,sizeof boundary,"--%.*s",(int)bl,b);size_t boundlen=strlen(boundary);
  char *fields=calloc(1,65536);if(!fields){cabecalho_pagina("Sem memória",NULL);rodape_pagina();return;}size_t used=0;
  const unsigned char *end=body+n,*cur=body;
  while(cur<end){const unsigned char *part=localizar_bytes(cur,(size_t)(end-cur),boundary,boundlen);if(!part)break;
    part+=boundlen;if(part+2>=end||(part[0]=='-'&&part[1]=='-'))break;
    if(part[0]!='\r'||part[1]!='\n'){cur=part;continue;}part+=2;
    const unsigned char *sep=localizar_bytes(part,(size_t)(end-part),"\r\n\r\n",4);if(!sep)break;
    size_t hlen=(size_t)(sep-part);if(hlen>2047)break;char h[2048];memcpy(h,part,hlen);h[hlen]=0;
    char *name=strstr(h,"name=\"");if(!name)break;name+=6;char *close=strchr(name,'"');if(!close)break;char key[64];size_t kl=(size_t)(close-name);if(kl>=sizeof key)break;memcpy(key,name,kl);key[kl]=0;
    const unsigned char *data=sep+4;char marker[130];snprintf(marker,sizeof marker,"\r\n%s",boundary);
    const unsigned char *next=localizar_bytes(data,(size_t)(end-data),marker,strlen(marker));if(!next)break;size_t sz=(size_t)(next-data);
    if(!strcmp(key,"imagem")&&strstr(h,"filename=\"")&&sz>0&&sz<=5*1024*1024){
      if(sz>=8&&!memcmp(data,"\x89PNG\r\n\x1a\n",8))strcpy(extensao_imagem_enviada,"png");
      else if(sz>=3&&data[0]==0xff&&data[1]==0xd8&&data[2]==0xff)strcpy(extensao_imagem_enviada,"jpg");
      else if(sz>=2&&data[0]=='B'&&data[1]=='M')strcpy(extensao_imagem_enviada,"bmp");
      if(extensao_imagem_enviada[0]){dados_imagem_enviada=malloc(sz);if(dados_imagem_enviada){memcpy(dados_imagem_enviada,data,sz);tamanho_imagem_enviada=sz;}}
    }else if(strcmp(key,"imagem")&&sz<4096)anexar_codificado(fields,65536,&used,key,data,sz);
    cur=next+2;
  }
  processar_acao(fields);free(fields);free(dados_imagem_enviada);dados_imagem_enviada=NULL;tamanho_imagem_enviada=0;extensao_imagem_enviada[0]=0;
}
// Inicializa o servidor HTTP, recebe solicitações e direciona para cada página.
int main(void){
#ifdef _WIN32  // Compila este trecho apenas quando a condição estiver definida.
WSADATA w;if(WSAStartup(MAKEWORD(2,2),&w)){puts("Erro Winsock");return 1;}
#endif  // Encerra o bloco de compilação condicional.
carregar();tipo_socket s=socket(AF_INET,SOCK_STREAM,0);if(s==(tipo_socket)-1){puts("Erro socket");return 1;}int yes=1;setsockopt(s,SOL_SOCKET,SO_REUSEADDR,(const char*)&yes,sizeof yes);struct sockaddr_in addr={0};addr.sin_family=AF_INET;addr.sin_port=htons(8765);addr.sin_addr.s_addr=htonl(INADDR_ANY);if(bind(s,(struct sockaddr*)&addr,sizeof addr)||listen(s,10)){puts("Porta 8765 indisponivel");return 1;}puts("MINHA BIBLIOTECA - servidor em C");puts("Neste PC: http://localhost:8765");puts("Celular na mesma rede: http://IP-DO-COMPUTADOR:8765");puts("Para encerrar: Ctrl+C");for(;;){cliente=accept(s,NULL,NULL);if(cliente==(tipo_socket)-1)continue;char *buf=malloc(TAMANHO_BUFFER+1);if(!buf){FECHAR_SOCKET(cliente);continue;}int got=recv(cliente,buf,TAMANHO_BUFFER,0);if(got<=0){free(buf);FECHAR_SOCKET(cliente);continue;}buf[got]=0;char method[8]={0},url[1024]={0};sscanf(buf,"%7s %1023s",method,url);char *body=strstr(buf,"\r\n\r\n");size_t len=0,have=0;char content_type[256]="";if(body){body+=4;char *p=strstr(buf,"Content-Length:");if(p)len=(size_t)strtoul(p+15,NULL,10);p=strstr(buf,"Content-Type:");if(p){p+=13;while(*p==' ')p++;size_t z=0;while(p[z]&&p[z]!='\r'&&z<sizeof content_type-1)z++;memcpy(content_type,p,z);content_type[z]=0;}have=(size_t)(got-(body-buf));while(have<len&&got<TAMANHO_BUFFER){int n=recv(cliente,buf+got,TAMANHO_BUFFER-got,0);if(n<=0)break;got+=n;have+=n;buf[got]=0;}}char *q=strchr(url,'?');if(q)*q++=0;if(!strcmp(method,"POST")&&body){if(len>TAMANHO_BUFFER-(size_t)(body-buf)||have<len){cabecalho_pagina("Envio muito grande ou incompleto",NULL);rodape_pagina();}else if(strstr(content_type,"multipart/form-data"))processar_formulario_com_imagem(content_type,(unsigned char*)body,len);else{body[len]=0;processar_acao(body);}}else if(!strncmp(url,"/capas/",7))enviar_capa(url);else if(!strcmp(url,"/"))painel_inicial();else if(!strcmp(url,"/livros"))pagina_livros(q);else if(!strcmp(url,"/livro"))formulario_livro(q);else if(!strcmp(url,"/usuarios"))pagina_usuarios(q);else if(!strcmp(url,"/usuario"))formulario_usuario(q);else if(!strcmp(url,"/emprestimos"))pagina_emprestimos();else if(!strcmp(url,"/novoemprestimo"))formulario_emprestimo(q);else{cabecalho_pagina("Página não encontrada",NULL);rodape_pagina();}free(buf);FECHAR_SOCKET(cliente);}FECHAR_SOCKET(s);liberar();return 0;}
